WITH registry AS (
-- Dataset: Loan Registry
-- Page: Delinquency and Portfolio Quality
-- Parameters: p_date_key = October 2026 (Text), p_product_id = All Products (Text), p_region_id = All Regions (Text), p_channel_id = All Channels (Text), p_min_dpd = 1+ DPD (Text)
-- Connection: CREDIT_PORTFOLIO | Mode: Direct

WITH bounds AS (SELECT (SELECT calendar_date FROM credit.calendar CROSS JOIN credit.dataset_run
 WHERE calendar_date=month_end AND to_char(calendar_date,'YYYYMMDD')::integer=${IF(p_date_key="October 2026",20261031,IF(p_date_key="September 2026",20260930,IF(p_date_key="August 2026",20260831,IF(p_date_key="July 2026",20260731,IF(p_date_key="June 2026",20260630,IF(p_date_key="May 2026",20260531,IF(p_date_key="April 2026",20260430,IF(p_date_key="March 2026",20260331,IF(p_date_key="February 2026",20260228,IF(p_date_key="January 2026",20260131,IF(p_date_key="December 2025",20251231,IF(p_date_key="November 2025",20251130,IF(p_date_key="October 2025",20251031,IF(p_date_key="September 2025",20250930,IF(p_date_key="August 2025",20250831,IF(p_date_key="July 2025",20250731,IF(p_date_key="June 2025",20250630,IF(p_date_key="May 2025",20250531,IF(p_date_key="April 2025",20250430,IF(p_date_key="March 2025",20250331,IF(p_date_key="February 2025",20250228,IF(p_date_key="January 2025",20250131,IF(p_date_key="December 2024",20241231,IF(p_date_key="November 2024",20241130,INT(p_date_key)))))))))))))))))))))))))}
 AND calendar_date BETWEEN report_start AND as_of_date) AS as_of_date,
      (date_trunc('month',(SELECT calendar_date FROM credit.calendar CROSS JOIN credit.dataset_run
 WHERE calendar_date=month_end AND to_char(calendar_date,'YYYYMMDD')::integer=${IF(p_date_key="October 2026",20261031,IF(p_date_key="September 2026",20260930,IF(p_date_key="August 2026",20260831,IF(p_date_key="July 2026",20260731,IF(p_date_key="June 2026",20260630,IF(p_date_key="May 2026",20260531,IF(p_date_key="April 2026",20260430,IF(p_date_key="March 2026",20260331,IF(p_date_key="February 2026",20260228,IF(p_date_key="January 2026",20260131,IF(p_date_key="December 2025",20251231,IF(p_date_key="November 2025",20251130,IF(p_date_key="October 2025",20251031,IF(p_date_key="September 2025",20250930,IF(p_date_key="August 2025",20250831,IF(p_date_key="July 2025",20250731,IF(p_date_key="June 2025",20250630,IF(p_date_key="May 2025",20250531,IF(p_date_key="April 2025",20250430,IF(p_date_key="March 2025",20250331,IF(p_date_key="February 2025",20250228,IF(p_date_key="January 2025",20250131,IF(p_date_key="December 2024",20241231,IF(p_date_key="November 2024",20241130,INT(p_date_key)))))))))))))))))))))))))}
 AND calendar_date BETWEEN report_start AND as_of_date))-interval '1 day')::date AS previous_date,
      date_trunc('month',(SELECT calendar_date FROM credit.calendar CROSS JOIN credit.dataset_run
 WHERE calendar_date=month_end AND to_char(calendar_date,'YYYYMMDD')::integer=${IF(p_date_key="October 2026",20261031,IF(p_date_key="September 2026",20260930,IF(p_date_key="August 2026",20260831,IF(p_date_key="July 2026",20260731,IF(p_date_key="June 2026",20260630,IF(p_date_key="May 2026",20260531,IF(p_date_key="April 2026",20260430,IF(p_date_key="March 2026",20260331,IF(p_date_key="February 2026",20260228,IF(p_date_key="January 2026",20260131,IF(p_date_key="December 2025",20251231,IF(p_date_key="November 2025",20251130,IF(p_date_key="October 2025",20251031,IF(p_date_key="September 2025",20250930,IF(p_date_key="August 2025",20250831,IF(p_date_key="July 2025",20250731,IF(p_date_key="June 2025",20250630,IF(p_date_key="May 2025",20250531,IF(p_date_key="April 2025",20250430,IF(p_date_key="March 2025",20250331,IF(p_date_key="February 2025",20250228,IF(p_date_key="January 2025",20250131,IF(p_date_key="December 2024",20241231,IF(p_date_key="November 2024",20241130,INT(p_date_key)))))))))))))))))))))))))}
 AND calendar_date BETWEEN report_start AND as_of_date))::date AS month_start),
    current_rows AS (SELECT s.* FROM credit.v_snapshot s CROSS JOIN bounds b
      WHERE s.snapshot_date=b.as_of_date AND (${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))}=0 OR s.product_id=${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))}) AND (${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))}=0 OR s.region_id=${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))}) AND (${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))}=0 OR s.channel_id=${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))})), eligible AS (SELECT * FROM current_rows WHERE principal_balance>0
      AND loan_status='Active' AND dpd>=greatest(${IF(p_min_dpd="All active",0,IF(p_min_dpd="1+ DPD",1,IF(p_min_dpd="31+ DPD",31,IF(p_min_dpd="91+ DPD",91,INT(p_min_dpd)))))},0)),
    ordered AS (SELECT *,row_number() OVER(
      ORDER BY dpd DESC,principal_balance DESC,loan_id) AS registry_row_no FROM eligible)
      SELECT e.snapshot_date,e.loan_id,e.loan_reference,e.customer_label,e.product_name,e.region_name,e.channel_name,
        e.principal_balance,e.overdue_principal,e.overdue_interest,e.dpd,e.dpd_bucket,
        to_char(e.principal_balance,'FM999,999,990.00') AS balance_label,
        to_char(e.overdue_principal,'FM999,999,990.00') AS overdue_principal_label,
        to_char(e.overdue_interest,'FM999,999,990.00') AS overdue_interest_label,
        e.dpd::text AS dpd_label,e.registry_row_no
      FROM ordered e
      ORDER BY e.registry_row_no
)
SELECT registry.*, 'http://localhost:37799/webroot/decision/v5/conf/subject/page/view/55f29d3962924a6692b2b3816cdafda6/report/f1e20436263842bb85acb6f4f88cb775?p_loan_id=' || registry.loan_id
      || '&p_date_key=' || to_char(registry.snapshot_date, 'YYYYMMDD')
      || '&As%20Of%20Month=' || replace(replace((CASE ${IF(p_date_key="October 2026",20261031,IF(p_date_key="September 2026",20260930,IF(p_date_key="August 2026",20260831,IF(p_date_key="July 2026",20260731,IF(p_date_key="June 2026",20260630,IF(p_date_key="May 2026",20260531,IF(p_date_key="April 2026",20260430,IF(p_date_key="March 2026",20260331,IF(p_date_key="February 2026",20260228,IF(p_date_key="January 2026",20260131,IF(p_date_key="December 2025",20251231,IF(p_date_key="November 2025",20251130,IF(p_date_key="October 2025",20251031,IF(p_date_key="September 2025",20250930,IF(p_date_key="August 2025",20250831,IF(p_date_key="July 2025",20250731,IF(p_date_key="June 2025",20250630,IF(p_date_key="May 2025",20250531,IF(p_date_key="April 2025",20250430,IF(p_date_key="March 2025",20250331,IF(p_date_key="February 2025",20250228,IF(p_date_key="January 2025",20250131,IF(p_date_key="December 2024",20241231,IF(p_date_key="November 2024",20241130,INT(p_date_key)))))))))))))))))))))))))} WHEN 20261031 THEN 'October 2026' WHEN 20260930 THEN 'September 2026' WHEN 20260831 THEN 'August 2026' WHEN 20260731 THEN 'July 2026' WHEN 20260630 THEN 'June 2026' WHEN 20260531 THEN 'May 2026' WHEN 20260430 THEN 'April 2026' WHEN 20260331 THEN 'March 2026' WHEN 20260228 THEN 'February 2026' WHEN 20260131 THEN 'January 2026' WHEN 20251231 THEN 'December 2025' WHEN 20251130 THEN 'November 2025' WHEN 20251031 THEN 'October 2025' WHEN 20250930 THEN 'September 2025' WHEN 20250831 THEN 'August 2025' WHEN 20250731 THEN 'July 2025' WHEN 20250630 THEN 'June 2025' WHEN 20250531 THEN 'May 2025' WHEN 20250430 THEN 'April 2025' WHEN 20250331 THEN 'March 2025' WHEN 20250228 THEN 'February 2025' WHEN 20250131 THEN 'January 2025' WHEN 20241231 THEN 'December 2024' WHEN 20241130 THEN 'November 2024' END), '+', '%2B'), ' ', '%20')
      || '&Product=' || replace(replace((CASE ${IF(p_product_id="All Products",0,IF(p_product_id="Personal Loan",1,IF(p_product_id="Auto Loan",2,IF(p_product_id="Mortgage",3,INT(p_product_id)))))} WHEN 0 THEN 'All Products' WHEN 1 THEN 'Personal Loan' WHEN 2 THEN 'Auto Loan' WHEN 3 THEN 'Mortgage' END), '+', '%2B'), ' ', '%20')
      || '&Region=' || replace(replace((CASE ${IF(p_region_id="All Regions",0,IF(p_region_id="Moscow",1,IF(p_region_id="Saint Petersburg",2,IF(p_region_id="Tatarstan",3,IF(p_region_id="Sverdlovsk Region",4,IF(p_region_id="Krasnodar Region",5,IF(p_region_id="Novosibirsk Region",6,INT(p_region_id))))))))} WHEN 0 THEN 'All Regions' WHEN 1 THEN 'Moscow' WHEN 2 THEN 'Saint Petersburg' WHEN 3 THEN 'Tatarstan' WHEN 4 THEN 'Sverdlovsk Region' WHEN 5 THEN 'Krasnodar Region' WHEN 6 THEN 'Novosibirsk Region' END), '+', '%2B'), ' ', '%20')
      || '&Channel=' || replace(replace((CASE ${IF(p_channel_id="All Channels",0,IF(p_channel_id="Branch",1,IF(p_channel_id="Online",2,IF(p_channel_id="Mobile App",3,IF(p_channel_id="Partner",4,INT(p_channel_id))))))} WHEN 0 THEN 'All Channels' WHEN 1 THEN 'Branch' WHEN 2 THEN 'Online' WHEN 3 THEN 'Mobile App' WHEN 4 THEN 'Partner' END), '+', '%2B'), ' ', '%20')
      || '&Registry%20Threshold=' || replace(replace((CASE ${IF(p_min_dpd="All active",0,IF(p_min_dpd="1+ DPD",1,IF(p_min_dpd="31+ DPD",31,IF(p_min_dpd="91+ DPD",91,INT(p_min_dpd)))))} WHEN 0 THEN 'All active' WHEN 1 THEN '1+ DPD' WHEN 31 THEN '31+ DPD' WHEN 91 THEN '91+ DPD' END), '+', '%2B'), ' ', '%20') AS loan_details_url
FROM registry ORDER BY registry_row_no
